function load(){try{return {...baseState(),...JSON.parse(localStorage.getItem(key)||"{}")}}catch{return baseState()}}
function save(){localStorage.setItem(key,JSON.stringify(state))}
function cleanText(value,max=500){return String(value??"").replace(/[<>]/g,"").slice(0,max)}
function exportDemoData(){
 const payload={schema:"obrien-portal-demo",version:1,exportedAt:new Date().toISOString(),source:location.origin,data:{statuses:state.statuses,activity:state.activity,services:state.services,decisions:state.decisions,requests:state.requests}};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),a=document.createElement("a");
 a.href=URL.createObjectURL(blob);a.download=`obrien-portal-demo-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0);
}
function normalizeImport(payload){
 if(!payload||payload.schema!=="obrien-portal-demo"||payload.version!==1||!payload.data)throw new Error("This is not an O'Brien portal demo export.");
 const allowedStatuses=new Set(["Draft","Sent","Viewed","Revision Requested","Accepted","Declined","Expired","Superseded"]),proposalIds=new Set(PROPOSALS.map(p=>p.id)),locationIds=new Set(LOCATIONS.map(l=>l.id)),data=payload.data;
 const statuses={...baseState().statuses};Object.entries(data.statuses||{}).forEach(([id,value])=>{if(proposalIds.has(id)&&allowedStatuses.has(value))statuses[id]=value});
 const activity=Array.isArray(data.activity)?data.activity.slice(-100).map(x=>({text:cleanText(x.text,300),at:cleanText(x.at,100)})):[];
 const services=Array.isArray(data.services)?data.services.slice(0,100).filter(x=>locationIds.has(x.locationId)).map(x=>({id:cleanText(x.id,100),locationId:x.locationId,type:cleanText(x.type,200),date:cleanText(x.date,100),window:cleanText(x.window,100),status:cleanText(x.status,60),technician:cleanText(x.technician,120),completion:cleanText(x.completion,120)})):[];
 const requests=Array.isArray(data.requests)?data.requests.slice(0,100).filter(x=>locationIds.has(x.locationId)).map(x=>({id:cleanText(x.id,100),locationId:x.locationId,unitId:cleanText(x.unitId,60),issue:cleanText(x.issue,160),priority:cleanText(x.priority,80),details:cleanText(x.details,1000),contact:cleanText(x.contact,160),createdAt:cleanText(x.createdAt,100),status:cleanText(x.status,80)})):[];
 const decisions={};Object.entries(data.decisions||{}).forEach(([id,value])=>{if(proposalIds.has(id)&&value&&typeof value==="object")decisions[id]={name:cleanText(value.name,160),title:cleanText(value.title,160),ack:cleanText(value.ack,20),at:cleanText(value.at,100),version:Number(value.version)||1}});
 return {statuses,activity:activity.length?activity:baseState().activity,services,decisions,requests};
}
function importDemoData(file){
 const reader=new FileReader();reader.onload=()=>{try{const session=state.session;state={...baseState(),...normalizeImport(JSON.parse(String(reader.result))),session};save();modal.classList.add("hidden");render();alert("Demo data imported into this browser. Local PDF selections are not included and must be selected again.")}catch(error){document.querySelector("#transfer-error").textContent=error.message||"The selected file could not be imported."}};reader.onerror=()=>{document.querySelector("#transfer-error").textContent="The selected file could not be read."};reader.readAsText(file);
}
function money(n){return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(n)}
