function loginView(){logout.classList.add("hidden");managerButton.classList.add("hidden");transferButton.classList.add("hidden");app.innerHTML=`<section class="login"><div><p class="kicker">O'BRIEN COMMERCIAL</p><h1>Every location.<em>One clear view.</em></h1><p class="lede">A presentation workspace for dealership proposals, condition reports and planned service visibility.</p><div class="notice">Authorized access only. Enter the email address and password provided by O'Brien AC.</div></div><form class="login-card" id="login-form"><h2>Customer login</h2><label class="field">Email<input name="email" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required></label><p class="error" id="login-error" role="alert"></p><button class="button primary">Sign in</button></form></section>`;
 document.querySelector("#login-form").onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget),email=String(d.get("email")).toLowerCase(),a=ACCOUNTS[email];if(!a||a.password!==d.get("password")){document.querySelector("#login-error").textContent="That email or password does not match.";return}state.session=email;save();go("#/dashboard")};
}
function nav(active){const a=account();return `<nav class="portal-nav" aria-label="Portal navigation"><button data-go="#/dashboard" class="${active==="dashboard"?"active":""}">Command center</button><button data-go="#/requests" class="${active==="requests"?"active":""}">Requests</button><button data-go="#/alerts" class="${active==="alerts"?"active":""}">Notifications</button><button data-go="#/capital" class="${active==="capital"?"active":""}">Capital plan</button><button data-go="#/report" class="${active==="report"?"active":""}">Executive report</button><button data-go="#/documents" class="${active==="documents"?"active":""}">Documents</button><button data-go="#/proposals" class="${active==="proposals"?"active":""}">Proposals</button><button data-go="#/services" class="${active==="services"?"active":""}">Service schedule</button><button data-go="#/presentation" class="${active==="presentation"?"active":""}">Presentation</button>${a.role==="admin"?`<button data-go="#/admin" class="${active==="admin"?"active":""}">Admin demo</button>`:""}</nav>`}
function wirePortalLinks(){document.querySelectorAll("[data-go]").forEach(el=>{el.onclick=()=>go(el.dataset.go);if(!["BUTTON","A"].includes(el.tagName)){el.setAttribute("role","link");el.setAttribute("tabindex","0");el.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();go(el.dataset.go)}}}})}
function shell(content,active){logout.classList.remove("hidden");managerButton.classList.remove("hidden");transferButton.classList.remove("hidden");app.innerHTML=`<div class="shell">${nav(active)}${content}</div>`;wirePortalLinks()}
function dashboard(){const a=account(),locs=allowedLocations(),props=PROPOSALS.filter(p=>locs.some(l=>l.id===p.locationId)),awaiting=props.filter(p=>["Sent","Viewed","Revision Requested"].includes(state.statuses[p.id])).length,critical=locs.filter(l=>LOCATION_INTELLIGENCE[l.id].tone==="critical").length,exposure=locs.reduce((sum,l)=>sum+LOCATION_INTELLIGENCE[l.id].exposure,0),health=Math.round(locs.reduce((sum,l)=>sum+LOCATION_INTELLIGENCE[l.id].score,0)/locs.length);shell(`<section class="hero executive-hero"><div><p class="kicker">MORGAN AUTOMOTIVE GROUP · EXECUTIVE COMMAND CENTER</p><h1>Portfolio intelligence.</h1><p class="lede">Condition, commercial decisions and service readiness across every authorized location.</p></div><div class="hero-meta"><span class="live-dot"></span> Portfolio snapshot<br><strong>${a.name}</strong><br>${a.role==="admin"?"O'Brien administrator":a.role==="group"?"Executive portfolio view":"Location operations view"}</div></section><section class="executive-strip"><article class="clickable-window" data-go="#/report"><span>Portfolio health</span><strong>${health}</strong><small>Open executive report →</small></article><article class="clickable-window" data-go="#/documents"><span>Action required</span><strong>${critical}</strong><small>Review priority documents →</small></article><article class="clickable-window" data-go="#/capital"><span>Documented exposure</span><strong>${money(exposure)}</strong><small>Open capital plan →</small></article><article class="clickable-window" data-go="#/proposals"><span>Decisions pending</span><strong>${awaiting}</strong><small>Review proposals →</small></article></section><section class="priority-brief"><div><p class="kicker">EXECUTIVE PRIORITY</p><h2>Two locations require action.</h2><p>Arrigo Sawgrass replacement priorities and Arrigo Margate drainage corrections represent the portfolio's most immediate documented needs.</p></div><button class="button primary" data-go="#/documents">Review critical documents</button></section><div class="section-title"><h2>Portfolio signals</h2><span>Priority intelligence and live workflow</span></div><section class="signal-grid">${PORTFOLIO_ALERTS.map(x=>`<button class="signal-card ${x.tone}" data-go="${x.route}"><span>${x.tone==="critical"?"Priority":"Upcoming"}</span><strong>${x.title}</strong><small>${x.detail}</small><b>${x.action} →</b></button>`).join("")}</section><div class="section-title"><h2>Location intelligence</h2><span>Status, score, exposure and next action</span></div><section class="grid">${locs.map(locationCard).join("")}</section><section class="split"><div class="panel"><div class="panel-heading"><h3>Upcoming service</h3><button class="text-link" data-go="#/services">View full schedule →</button></div>${serviceRows(state.services.filter(s=>locs.some(l=>l.id===s.locationId)).slice(0,3))}</div><div class="panel"><div class="panel-heading"><h3>Recent activity</h3><button class="text-link" data-go="#/documents">Open documents →</button></div><ul class="timeline">${state.activity.slice(-5).reverse().map(x=>`<li>${x.text}<small>${x.at}</small></li>`).join("")}</ul></div></section>`,"dashboard");document.querySelectorAll("[data-location]").forEach(c=>c.onclick=()=>go(`#/location/${c.dataset.location}`))}
function locationCard(l){const intel=LOCATION_INTELLIGENCE[l.id];return `<article tabindex="0" class="location-card ${l.photo?"photo":""} ${l.featured?"elite-feature":""}" ${l.photo?`style="background-image:url('${l.photo}')"`:""} data-location="${l.id}">${l.featured?`<span class="feature-ribbon">FEATURE HIGHLIGHT</span>`:""}<span class="status-pill ${intel.tone}">${intel.status}</span>${l.logo?`<img class="location-logo" src="${l.logo}" alt="${l.brand} logo">`:`<div class="brand-word ${l.brand.toLowerCase().split(" ")[0]}">${l.brand}</div>`}<h3>${l.name}</h3><p>${l.address}</p><div class="card-intelligence"><span><b>${intel.score}</b>Connected</span><span><b>${intel.exposure?money(intel.exposure):l.featured?"24/7":"—"}</b>${l.featured?"Visibility":"Exposure"}</span><span><b>${intel.next}</b>Next</span></div><footer><span>${l.featured?"Explore Elite membership":"Open command center"}</span><span>→</span></footer></article>`}
function locationContactCard(l){const c=LOCATION_CONTACTS[l.id],first=l.id==="bmw-coconut-creek"?COCONUT_EQUIPMENT[0]:ARRIGO_EQUIPMENT[l.id]?.units[0];return `<section class="contact-strip"><div><span>Location contact</span><strong>${c.name}</strong><small>${c.facility}</small></div><div><span>Operating hours</span><strong>${c.hours}</strong><small>${c.access}</small></div><div><span>Emergency support</span><strong>${c.emergency}</strong><small>Assigned account manager: Chad Oberstein</small></div><div class="actions"><button class="button" id="contact-manager">Contact manager</button>${first?`<button class="button" data-asset-location="${l.id}" data-asset-unit="${first.id}">Asset detail demo</button>`:""}</div></section>`}
function proposalsView(locationId){const locs=allowedLocations(),props=PROPOSALS.filter(p=>(!locationId||p.locationId===locationId)&&locs.some(l=>l.id===p.locationId));return `<div class="section-title"><h2>Maintenance proposals</h2><span>Supplied proposal figures</span></div>${props.map(proposalCard).join("")||`<div class="empty">No proposals are assigned to this account.</div>`}`}
function proposalFile(id){return files[id]||null}
function proposalCard(p){const l=LOCATIONS.find(x=>x.id===p.locationId),status=state.statuses[p.id],annual=Math.round(p.standalone*.88),hasLocal=Boolean(proposalFile(p.id));return `<article class="proposal"><div><span class="badge ${status.toLowerCase().replaceAll(" ","-")}">${status}</span><h3>${l.name} · ${p.title}</h3><p>${p.reference} · Version ${p.version} · Issued ${p.date}</p><small class="privacy-note">${hasLocal?"Local PDF selected for this browser":"Confidential PDF not published · select it locally to preview"}</small><div class="actions"><button class="button primary" data-select="${p.id}">${hasLocal?"Replace local PDF":"Select local PDF"}</button><button class="button" data-view="${p.id}">View Proposal</button><button class="button" data-open="${p.id}">Open in New Tab</button><button class="button" data-download="${p.id}">Download PDF</button>${["Sent","Viewed"].includes(status)?`<button class="button" data-revision="${p.id}">Request revision</button><button class="button primary" data-accept="${p.id}">Demo accept</button>`:""}</div></div><div class="price"><small>7-account portfolio</small><strong>${money(annual)}</strong><small>${money(Math.round(annual/12))}/month · saves ${money(p.benchmark-annual)} (20.8%)</small></div><div><span class="badge">12% portfolio tier</span><p>Standalone ${money(p.standalone)} · benchmark ${money(p.benchmark)}</p></div></article>`}
function requireProposalFile(id,action){const file=proposalFile(id);if(file)return action(file);pickFile(id);return null}
function wireProposalActions(){document.querySelectorAll("[data-select]").forEach(b=>b.onclick=()=>pickFile(b.dataset.select));document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>requireProposalFile(b.dataset.view,()=>{const id=b.dataset.view;if(state.statuses[id]==="Sent"){state.statuses[id]="Viewed";activity(`Proposal opened: ${PROPOSALS.find(p=>p.id===id).reference}`);save()}preview(id)}));document.querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>requireProposalFile(b.dataset.open,f=>window.open(f.url,"_blank","noopener")));document.querySelectorAll("[data-download]").forEach(b=>b.onclick=()=>requireProposalFile(b.dataset.download,f=>{const a=document.createElement("a");a.href=f.url;a.download=f.name;a.click()}));document.querySelectorAll("[data-revision]").forEach(b=>b.onclick=()=>setStatus(b.dataset.revision,"Revision Requested","Demo revision requested"));document.querySelectorAll("[data-accept]").forEach(b=>b.onclick=()=>decisionModal(b.dataset.accept))}
function proposals(){shell(`${proposalsView()}<section class="panel proposal-help"><div><p class="kicker">PROPOSAL SUPPORT</p><h3>Need scope clarification or a revision?</h3><p>Contact your assigned account manager before recording a demo decision.</p></div><button class="button" id="proposal-question">Ask a question</button></section>`,"proposals");wireProposalActions();document.querySelector("#proposal-question").onclick=accountManagerModal}
function locationProposalDocuments(l){return [l.proposalDocument,...(l.additionalProposalDocuments||[])].filter(Boolean)}
function documentRecords(){const records=[];LOCATIONS.forEach(l=>{locationProposalDocuments(l).forEach(p=>records.push({location:l,type:"Proposal",title:p.title,date:p.date,url:p.url,tone:"proposal"}));if(l.conditionReport)records.push({location:l,type:"Condition report",title:l.conditionReport.title,date:l.conditionReport.date,url:l.conditionReport.url,tone:"condition"});if(l.plans)records.push({location:l,type:"Plans",title:l.plans.title,date:l.plans.date,url:l.plans.url,tone:"plans"})});Object.entries(COCONUT_DOCS).forEach(([type,d])=>records.push({location:LOCATIONS[0],type:type[0].toUpperCase()+type.slice(1),title:d.name,date:"Demo document",url:d.url,tone:"demo"}));return records}
function documents(){const records=documentRecords().filter(d=>allowedLocations().some(l=>l.id===d.location.id));shell(`<section class="hero"><div><p class="kicker">CONTROLLED DOCUMENT WORKSPACE</p><h1>Document center.</h1><p class="lede">A unified index for proposals, condition reports, agreements, plans and service records.</p></div><div class="hero-meta"><strong>${records.length}</strong><br>Indexed documents<br><small>Static demonstration library</small></div></section><div class="document-toolbar"><label class="field">Search documents<input id="document-search" type="search" placeholder="Location, document or type"></label><label class="field">Document type<select id="document-filter"><option value="all">All documents</option><option>Proposal</option><option>Condition report</option><option>Plans</option><option>Equipment</option><option>Agreement</option><option>Upcoming</option><option>History</option></select></label></div><section class="document-library" id="document-library">${records.map(d=>`<article class="document-card" data-document-search="${`${d.location.name} ${d.type} ${d.title}`.toLowerCase()}" data-document-type="${d.type}"><div><span class="document-icon ${d.tone}">${d.type.slice(0,2).toUpperCase()}</span><p class="kicker">${d.type}</p><h3>${d.title}</h3><p>${d.location.name} · ${d.date}</p></div><div class="actions"><a class="button primary" href="${d.url}" target="_blank" rel="noopener">View document</a><a class="button" href="${d.url}" download>Download</a></div></article>`).join("")}</section><p class="notice">Static demo notice: published files use public URLs. Real confidential records require server-enforced authentication and private object storage.</p>`,"documents");const search=document.querySelector("#document-search"),filter=document.querySelector("#document-filter"),apply=()=>document.querySelectorAll(".document-card").forEach(card=>card.classList.toggle("hidden",!card.dataset.documentSearch.includes(search.value.toLowerCase())||(filter.value!=="all"&&card.dataset.documentType!==filter.value)));search.oninput=apply;filter.onchange=apply}
function coconutOverview(){return `<section class="location-summary"><article class="score-card"><p class="kicker">PORTFOLIO READINESS</p><strong>92</strong><span>Sample condition score</span><div class="score-track"><i style="width:92%"></i></div></article><article class="panel executive"><span class="badge viewed">Proposal ready</span><h2>Preventive care, clearly documented.</h2><p>Four planned maintenance rounds with proposal-aligned reporting, decision history and service visibility for BMW of Coconut Creek.</p><div class="mini-metrics"><span><b>04</b>Rounds / year</span><span><b>$28,512</b>Portfolio price</span><span><b>20.8%</b>Portfolio savings</span></div></article></section><div class="section-title"><h2>Location command center</h2><span>Demonstration workspace</span></div><section class="feature-grid"><button data-location-tab="equipment"><span>01</span><strong>Equipment</strong><small>Unit registry, operating status and issue reporting</small></button><button data-location-tab="condition"><span>02</span><strong>Condition Reports</strong><small>Asset health, findings and recommended priorities</small></button><button data-location-tab="agreement"><span>03</span><strong>Agreement</strong><small>Exact proposal reference, scope and commercial terms</small></button><button data-location-tab="upcoming"><span>04</span><strong>Upcoming Service</strong><small>Visit window, readiness and planned checklist</small></button><button data-location-tab="history"><span>05</span><strong>Service History</strong><small>Auditable sample timeline and closeout records</small></button></section>`}
function demoDocActions(key,label){return `<div class="document-actions"><button type="button" class="button primary" data-demo-doc="${key}">View ${label}</button><button type="button" class="button" data-demo-open="${key}">Open PDF</button><button type="button" class="button" data-demo-download="${key}">Download</button></div>`}
function coconutEquipment(){const requests=(state.requests||[]).filter(r=>r.locationId==="bmw-coconut-creek");return `<div class="section-title"><h2>Equipment registry</h2><span>${COCONUT_EQUIPMENT.length} sample units · Demo inventory</span></div>${demoDocActions("equipment","equipment PDF")}<section class="equipment-toolbar"><div><p class="kicker">BMW OF COCONUT CREEK</p><h2>Every unit. One service path.</h2><p>Select a unit to report loss of cooling, unusual operation or a service need.</p></div><div class="equipment-summary"><span><b>${COCONUT_EQUIPMENT.length}</b>Units</span><span><b>${COCONUT_EQUIPMENT.filter(x=>x.status==="Operational").length}</b>Operational</span><span><b>${requests.length}</b>Open demo requests</span></div></section><section class="equipment-grid">${COCONUT_EQUIPMENT.map(unit=>`<article class="equipment-card"><header><span class="unit-id">${unit.id}</span><span class="unit-state ${unit.status.toLowerCase()}">${unit.status}</span></header><h3>${unit.name}</h3><p>${unit.type} · ${unit.capacity}</p><dl><div><dt>Location</dt><dd>${unit.name}</dd></div><div><dt>Service record</dt><dd>${unit.lastService}</dd></div></dl><button type="button" class="button ${unit.status==="Priority"?"primary":""}" data-report-unit="${unit.id}">Report an issue</button></article>`).join("")}</section><div class="section-title"><h2>Open requests</h2><span>Stored only in this browser</span></div>${requests.length?`<section class="request-list">${requests.slice().reverse().map(r=>`<article><span class="badge sent">Open demo request</span><div><h3>${r.unitId} · ${r.issue}</h3><p>${r.details||"No additional details provided."}</p><small>${r.priority} priority · ${r.createdAt}</small></div></article>`).join("")}</section>`:`<div class="empty">No issues have been reported for this demo location.</div>`}`}
function coconutCondition(){return `<div class="section-title"><h2>Condition report</h2><span>Sample report · Not an actual inspection</span></div>${demoDocActions("condition","condition report")}<section class="report-hero"><div><p class="kicker">BMW OF COCONUT CREEK</p><h2>Operational readiness</h2><p>Demonstration condition snapshot designed to show the reporting standard included with the maintenance program.</p></div><div class="health-ring"><strong>92</strong><span>Sample score</span></div></section><section class="condition-grid"><article class="condition-card good"><span>Airflow</span><strong>Ready</strong><p>Sample: supply and return pathways recorded as clear.</p></article><article class="condition-card good"><span>Electrical</span><strong>Stable</strong><p>Sample: connections and contactors included in inspection scope.</p></article><article class="condition-card watch"><span>Drainage</span><strong>Monitor</strong><p>Sample: condensate treatment scheduled during the first round.</p></article><article class="condition-card good"><span>Controls</span><strong>Online</strong><p>Sample: thermostat response and setpoints included in verification.</p></article></section><section class="panel checklist"><h3>First-round field checklist</h3><div><span>✓ Replace or document filter condition</span><span>✓ Clear and treat condensate lines</span><span>✓ Record refrigerant operating data</span><span>✓ Inspect belts, bearings and electrical connections</span><span>✓ Photograph priority findings</span><span>✓ Deliver executive closeout summary</span></div></section>`}
function coconutAgreement(){return `<div class="section-title"><h2>Agreement workspace</h2><span>Aligned to proposal OB-PM-2026-1008-01</span></div>${demoDocActions("agreement","agreement summary")}<section class="agreement-hero"><div><p class="kicker">COMMERCIAL HVAC MAINTENANCE</p><h2>BMW of Coconut Creek</h2><p>Version 1 · Issued October 8, 2026 · Proposal validity: 30 days</p></div><span class="badge sent">Pending review</span></section><section class="terms-grid"><article><small>Portfolio investment</small><strong>$28,512</strong><span>$2,376 / month</span></article><article><small>Standalone proposal</small><strong>$32,400</strong><span>$2,700 / month</span></article><article><small>Scheduled coverage</small><strong>04</strong><span>Rounds per year</span></article><article><small>Portfolio advantage</small><strong>20.8%</strong><span>$7,488 projected savings</span></article></section><section class="split"><article class="panel"><h3>Included program framework</h3><ul class="premium-list"><li>Four planned preventive-maintenance rounds</li><li>Proposal-version and decision tracking</li><li>Condition reporting with photographic findings</li><li>Service scheduling and closeout visibility</li></ul></article><article class="panel"><h3>Proposal document</h3><p class="lede">Review the exact supplied document attached to this location.</p><div class="actions"><button type="button" class="button primary" data-view="proposal-bmw-coconut-creek-v1">View proposal</button><button type="button" class="button" data-download="proposal-bmw-coconut-creek-v1">Download PDF</button></div></article></section>`}
function coconutUpcoming(){const items=state.services.filter(s=>s.locationId==="bmw-coconut-creek");return `<div class="section-title"><h2>Upcoming service</h2><span>Demo schedule</span></div>${demoDocActions("upcoming","work order PDF")}<section class="visit-card"><div class="visit-date"><strong>22</strong><span>OCT<br>2026</span></div><div><p class="kicker">ROUND 01 · PREVENTIVE MAINTENANCE</p><h2>Site readiness visit</h2><p>8:00 AM–12:00 PM · Technician assignment pending</p></div><span class="badge sent">Proposed</span></section><section class="split"><article class="panel"><h3>Planned field sequence</h3><ol class="sequence"><li><b>01</b><span>Arrival and site coordination<small>Confirm access, safety requirements and priority areas.</small></span></li><li><b>02</b><span>Equipment assessment<small>Document operating condition and baseline readings.</small></span></li><li><b>03</b><span>Preventive service<small>Complete proposal-aligned maintenance checklist.</small></span></li><li><b>04</b><span>Digital closeout<small>Publish findings, photographs and recommendations.</small></span></li></ol></article><article class="panel"><h3>Visit readiness</h3><div class="readiness"><span><i class="done"></i>Location confirmed</span><span><i class="done"></i>Scope attached</span><span><i></i>Primary contact assignment</span><span><i></i>Technician assignment</span></div></article></section>${items.length?`<div class="panel compact-services">${serviceRows(items)}</div>`:""}`}
function coconutHistory(){return `<div class="section-title"><h2>Service history</h2><span>Sample records · No actual work represented</span></div>${demoDocActions("history","service history PDF")}<section class="history-ledger"><article><time>OCT 08<br>2026</time><div><span class="badge viewed">Documented</span><h3>Maintenance proposal issued</h3><p>OB-PM-2026-1008-01 · Version 1 added to the location workspace.</p></div><b>Proposal</b></article><article><time>OCT 10<br>2026</time><div><span class="badge">Sample</span><h3>Portfolio review prepared</h3><p>Commercial terms and four-round maintenance structure staged for review.</p></div><b>Planning</b></article><article><time>OCT 22<br>2026</time><div><span class="badge sent">Proposed</span><h3>First preventive-maintenance round</h3><p>Demonstration appointment only. No service completion is claimed.</p></div><b>Upcoming</b></article></section>`}
function coconutPanel(tab){if(tab==="equipment")return coconutEquipment();if(tab==="condition")return coconutCondition();if(tab==="agreement")return coconutAgreement();if(tab==="upcoming")return coconutUpcoming();if(tab==="history")return coconutHistory();return coconutOverview()}
function conditionLocationOverview(l){const equipment=ARRIGO_EQUIPMENT[l.id];return `<section class="location-summary"><article class="score-card condition-account"><p class="kicker">CONDITION REPORT</p><strong>${l.conditionReport.metric.split(" ")[0]}</strong><span>${l.conditionReport.metric.replace(/^\S+\s*/,"")}</span><div class="score-track"><i style="width:100%"></i></div></article><article class="panel executive"><span class="badge viewed">Presentation ready</span><h2>${l.conditionReport.title}</h2><p>${l.conditionReport.summary}</p><div class="mini-metrics"><span><b>${equipment.total}</b>Covered units</span><span><b>${l.conditionReport.date}</b>Report date</span><span><b>${locationProposalDocuments(l).length}</b>Proposal document${locationProposalDocuments(l).length===1?"":"s"}</span></div></article></section><div class="section-title"><h2>Location command center</h2><span>Equipment, documents and next actions</span></div><section class="feature-grid condition-feature"><button data-location-tab="equipment"><span>01</span><strong>Equipment</strong><small>Review documented unit status, field findings and service requests</small></button><button data-location-tab="proposal"><span>02</span><strong>Proposal</strong><small>Review scope, pricing, options and authorization terms</small></button><button data-location-tab="condition"><span>03</span><strong>Condition Reports</strong><small>Review findings, photographs and recommended priorities</small></button><button data-condition-open="${l.id}"><span>04</span><strong>Open field report</strong><small>Open the complete supplied condition report in a separate tab</small></button></section>`}
function equipmentTone(status){if(["Operational","Good"].includes(status))return "operational";if(["Monitor","Service Review","Planned Replacement","Drain Concern"].includes(status))return "monitor";return "priority"}
function conditionEquipmentPanel(l){const inventory=ARRIGO_EQUIPMENT[l.id],requests=(state.requests||[]).filter(r=>r.locationId===l.id),good=inventory.units.filter(x=>["Operational","Good"].includes(x.status)).length,priority=inventory.units.filter(x=>equipmentTone(x.status)==="priority").length,margateNote=l.id==="arrigo-margate"?" Any unidentified Margate drain areas remain unassigned until field records provide a unit number.":" Field verification remains required before approved work.";return `<div class="section-title"><h2>Equipment intelligence</h2><span>Aligned to supplied condition report</span></div><section class="equipment-toolbar equipment-command"><div><p class="kicker">${inventory.eyebrow}</p><h2>${inventory.title}</h2><p>${inventory.summary}</p></div><div class="equipment-summary"><span><b>${inventory.total}</b>Covered units</span><span><b>${good}</b>Confirmed good</span><span><b>${priority}</b>Immediate / replace</span><span><b>${requests.length}</b>Open requests</span></div></section><div class="evidence-note"><strong>REPORT BASIS</strong><span>${inventory.note}</span><button class="button" data-condition-view="${l.id}">View source report</button></div><section class="equipment-grid condition-equipment-grid">${inventory.units.map(unit=>`<article class="equipment-card"><header><span class="unit-id">${unit.id}</span><span class="unit-state ${equipmentTone(unit.status)}">${unit.status}</span></header><h3>${unit.name}</h3><p>${unit.area}</p><dl><div><dt>Finding</dt><dd>${unit.finding}</dd></div><div><dt>Next action</dt><dd>${unit.action}</dd></div></dl><button type="button" class="button ${equipmentTone(unit.status)==="priority"?"primary":""}" data-report-location="${l.id}" data-report-unit="${unit.id}">Report service need</button></article>`).join("")}</section><div class="section-title"><h2>Service requests</h2><span>Browser-local presentation workflow</span></div>${requests.length?`<section class="request-list">${requests.slice().reverse().map(r=>`<article><span class="badge sent">${r.status}</span><div><h3>${r.unitId} · ${r.issue}</h3><p>${r.details||"No additional details provided."}</p><small>${r.priority} priority · ${r.createdAt}</small></div></article>`).join("")}</section>`:`<div class="empty">No service needs have been recorded for this location.</div>`}<p class="notice">Equipment details reproduce the supplied condition-report findings.${margateNote}</p>`}
function proposalDocumentPanel(l){const proposals=locationProposalDocuments(l);return `<div class="section-title"><h2>Replacement proposals</h2><span>${proposals.length} supplied documents</span></div>${proposals.map((p,index)=>`<section class="report-hero proposal-document"><div><p class="kicker">${l.brand} · ${p.reference}</p><h2>${p.title}</h2><p>${p.summary}</p><div class="actions"><button type="button" class="button primary" data-location-proposal-view="${l.id}" data-proposal-index="${index}">View proposal</button><button type="button" class="button" data-location-proposal-open="${l.id}" data-proposal-index="${index}">Open PDF</button><button type="button" class="button" data-location-proposal-download="${l.id}" data-proposal-index="${index}">Download</button></div></div><div class="proposal-value"><small>Proposal investment</small><strong>${p.metric}</strong><span>${p.detail}</span><small>Issued ${p.date}</small></div></section>`).join("")}<div class="notice">These are the supplied proposals for ${l.name}. Review each complete PDF for equipment schedules, inclusions, exclusions, validity and authorization terms.</div>`}
function plansPanel(l){const p=l.plans;return `<div class="section-title"><h2>Plans</h2><span>${p.date}</span></div><section class="report-hero"><div><p class="kicker">${l.brand}</p><h2>${p.title}</h2><p>${p.summary}</p><div class="actions"><a class="button primary" href="${p.url}" target="_blank" rel="noopener">Open plans</a><a class="button" href="${p.url}" download>Download PDF</a></div></div><div class="health-ring report-count"><strong>${p.metric.split(" ")[0]}</strong><span>${p.metric.replace(/^\S+\s*/,"")}</span></div></section><section class="panel plan-viewer"><iframe src="${p.url}" title="${l.name} electrical plans"></iframe></section><div class="notice">This is the supplied electrical plan set for ${l.name}. Use the complete PDF for sheet-level detail, notes, symbols and dimensions.</div>`}
function wirePlansActions(){}
function conditionReportPanel(l){return `<div class="section-title"><h2>Condition report</h2><span>${l.conditionReport.date}</span></div><section class="report-hero"><div><p class="kicker">${l.brand}</p><h2>${l.conditionReport.title}</h2><p>${l.conditionReport.summary}</p><div class="actions"><button type="button" class="button primary" data-condition-view="${l.id}">View report</button><button type="button" class="button" data-condition-open="${l.id}">Open PDF</button><button type="button" class="button" data-condition-download="${l.id}">Download</button></div></div><div class="health-ring report-count"><strong>${l.conditionReport.metric.split(" ")[0]}</strong><span>${l.conditionReport.metric.replace(/^\S+\s*/,"")}</span></div></section><div class="notice">This is the supplied field condition report for ${l.name}. Review the complete PDF for photographs, unit-level findings, limitations and recommended corrective action.</div>`}
function genericLocationPanel(tab,l){if(tab==="equipment"&&ARRIGO_EQUIPMENT[l.id])return conditionEquipmentPanel(l);if(tab==="proposal")return l.proposalDocument?proposalDocumentPanel(l):proposalsView(l.id);if(tab==="plans"&&l.plans)return plansPanel(l);if(tab==="condition"&&l.conditionReport)return conditionReportPanel(l);if(tab==="upcoming")return `<div class="section-title"><h2>Upcoming services</h2><span>Location schedule</span></div><section class="panel">${serviceRows(state.services.filter(s=>s.locationId===l.id))||`<div class="empty">No demonstration appointments.</div>`}</section>`;if(l.conditionReport)return conditionLocationOverview(l);return `${proposalsView(l.id)}<section class="panel" id="services"><h3>Upcoming services</h3>${serviceRows(state.services.filter(s=>s.locationId===l.id))||`<div class="empty">No demonstration appointments.</div>`}</section>`}
function thermostatEntities(){return homeAssistantSession.entities.filter(x=>x.entity_id?.startsWith("climate."))}
function temperatureValue(value){const n=Number(value);return Number.isFinite(n)?`${Math.round(n)}°`:"—"}
function residentialPanel(){const climates=thermostatEntities();return `<section class="residential-live"><div class="live-header"><div><p class="kicker">O'BRIEN ELITE · CONNECTED COMFORT</p><h2>Always connected. Always informed.</h2><p>${homeAssistantSession.connected?`Connected securely for this browser session · ${climates.length} climate device${climates.length===1?"":"s"}`:"Connect Home Assistant to bring live thermostat visibility, comfort insights and faster service context into your Elite membership."}</p></div><div class="actions"><button class="button primary" id="connect-home-assistant">${homeAssistantSession.connected?"Refresh live status":"Connect Home Assistant"}</button>${homeAssistantSession.connected?`<button class="button" id="disconnect-home-assistant">Disconnect</button>`:""}</div></div>${homeAssistantSession.error?`<div class="ha-error">${cleanText(homeAssistantSession.error,300)}</div>`:""}<div class="elite-benefits"><article><span>01</span><strong>Live comfort visibility</strong><small>See temperature, humidity, mode and setpoint at a glance.</small></article><article><span>02</span><strong>Informed service</strong><small>Give the O'Brien team better context before the visit.</small></article><article><span>03</span><strong>One connected record</strong><small>Bring equipment status and membership support together.</small></article></div><div class="thermostat-grid">${climates.length?climates.map(entity=>{const a=entity.attributes||{},name=cleanText(a.friendly_name||entity.entity_id,100),mode=cleanText(entity.state||"unknown",30),hvac=cleanText(a.hvac_action||"idle",30);return `<article class="thermostat-card"><header><span class="live-dot"></span><b>${name}</b><span class="mode">${mode}</span></header><div class="temperature"><strong>${temperatureValue(a.current_temperature)}</strong><span>Current</span></div><dl><div><dt>Target</dt><dd>${temperatureValue(a.temperature)}</dd></div><div><dt>System</dt><dd>${hvac}</dd></div><div><dt>Humidity</dt><dd>${a.current_humidity==null?"—":`${Math.round(Number(a.current_humidity))}%`}</dd></div></dl><small>Updated live from Home Assistant</small></article>`}).join(""):`<article class="thermostat-card placeholder"><span class="home-glyph">⌂</span><h3>1st Floor</h3><p>Temperature, setpoint, humidity and operating mode will appear after connection.</p></article><article class="thermostat-card placeholder"><span class="home-glyph">⌂</span><h3>Upstairs</h3><p>Live Resideo status is ready to map from Home Assistant.</p></article>`}</div><section class="panel privacy-panel"><div><p class="kicker">PRIVATE CONNECTION</p><h3>Your access token is never committed or uploaded.</h3><p>The token stays in memory for this browser tab and is cleared when the tab closes. A public production portal should use an authenticated server-side relay, not an embedded Home Assistant credential.</p></div><span class="connection-state ${homeAssistantSession.connected?"online":""}">${homeAssistantSession.connected?"LIVE":"SETUP REQUIRED"}</span></section></section>`}
function homeAssistantModal(){modal.classList.remove("hidden");modal.innerHTML=`<form class="modal-card" id="ha-connect-form"><button type="button" class="ghost modal-close">Close</button><p class="kicker">HOME ASSISTANT LIVE CONNECTION</p><h2 id="modal-title">Connect residential status</h2><p class="notice">Use a Home Assistant long-lived access token. It is held only in this tab's memory and is never saved to the repository or portal storage.</p><label class="field">Home Assistant URL<input name="url" type="url" value="${cleanText(homeAssistantSession.url,200)}" placeholder="https://your-home-assistant.example" required></label><label class="field">Long-lived access token<input name="token" type="password" autocomplete="off" required></label><button class="button primary" type="submit">Connect securely</button><p class="error" id="ha-connect-error"></p><p class="privacy-note">For the public HTTPS portal, use an HTTPS Home Assistant URL such as Home Assistant Cloud. Browsers normally block an HTTPS page from reading an HTTP-only local address.</p></form>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("#ha-connect-form").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector("button[type=submit]"),error=document.querySelector("#ha-connect-error");button.disabled=true;button.textContent="Connecting…";error.textContent="";try{homeAssistantSession.url=String(d.url).replace(/\/$/,"");homeAssistantSession.token=String(d.token);await refreshHomeAssistant();sessionStorage.setItem("obrienHaUrl",homeAssistantSession.url);modal.classList.add("hidden");locationView("morgan-residence")}catch(err){error.textContent=homeAssistantSession.error||err.message||"Connection failed.";button.disabled=false;button.textContent="Connect securely"}}}
async function refreshHomeAssistant(){homeAssistantSession.error="";try{const response=await fetch(`${homeAssistantSession.url}/api/states`,{headers:{Authorization:`Bearer ${homeAssistantSession.token}`,"Content-Type":"application/json"}});if(!response.ok)throw new Error(`Home Assistant returned ${response.status}.`);const entities=await response.json();homeAssistantSession.entities=Array.isArray(entities)?entities:[];homeAssistantSession.connected=true}catch(error){homeAssistantSession.connected=false;homeAssistantSession.entities=[];homeAssistantSession.error=location.protocol==="https:"&&homeAssistantSession.url.startsWith("http:")?"This HTTPS portal cannot read an HTTP-only Home Assistant address. Use an HTTPS Home Assistant Cloud URL or a secure server-side relay.":`Unable to reach Home Assistant. ${error.message||"Check the URL, token and CORS settings."}`;throw error}}
function wireResidential(){document.querySelector("#connect-home-assistant")?.addEventListener("click",async()=>{if(!homeAssistantSession.connected)return homeAssistantModal();try{await refreshHomeAssistant()}catch{}locationView("morgan-residence")});document.querySelector("#disconnect-home-assistant")?.addEventListener("click",()=>{homeAssistantSession={...homeAssistantSession,token:"",entities:[],connected:false,error:""};locationView("morgan-residence")})}
function locationView(id){const l=allowedLocations().find(x=>x.id===id);if(!l)return go("#/dashboard");const elite=id==="bmw-coconut-creek",residential=Boolean(l.residential),conditionAccount=Boolean(l.conditionReport),tabs=residential?`<button type="button" class="active" data-location-tab="overview">Live Status</button>`:conditionAccount?`<button type="button" class="active" data-location-tab="overview">Overview</button><button type="button" data-location-tab="equipment">Equipment</button><button type="button" data-location-tab="proposal">Proposal</button>${l.plans?`<button type="button" data-location-tab="plans">Plans</button>`:""}<button type="button" data-location-tab="condition">Condition Reports</button><button type="button" data-location-tab="upcoming">Upcoming Services</button>`:`<button type="button" class="active" data-location-tab="overview">Overview</button><button type="button" data-location-tab="equipment">Equipment</button><button type="button" data-location-tab="proposal">Proposal</button><button type="button" data-location-tab="condition">Condition Reports</button><button type="button" data-location-tab="agreement">Agreement</button><button type="button" data-location-tab="upcoming">Upcoming Services</button><button type="button" data-location-tab="history">Service History</button>`;shell(`<button type="button" class="ghost" data-go="#/dashboard">← Portfolio</button><section class="hero location-hero" ${l.photo?`style="--location-photo:url('${l.photo}')"`:""}><div>${l.logo?`<img class="location-hero-logo" src="${l.logo}" alt="${l.brand} logo">`:`<p class="kicker">${l.brand}</p>`}<h1>${l.name}</h1><p class="lede">${l.address}<br>Assigned account manager: Chad Oberstein · Operation Manager</p></div></section>${residential?"":locationContactCard(l)}<div class="tabs location-tabs">${tabs}</div><section id="location-workspace">${residential?residentialPanel():elite?coconutPanel("overview"):genericLocationPanel("overview",l)}</section>${elite?`<p class="notice elite-notice">This elite workspace contains proposal-aligned demonstration data. Equipment, condition findings, appointments, service requests and service-history entries are samples and do not represent completed or dispatched field work.</p>`:""}`,"dashboard");if(!residential)document.querySelector("#contact-manager").onclick=accountManagerModal;document.querySelectorAll(".location-tabs [data-location-tab]").forEach(b=>b.onclick=()=>activateLocationTab(b.dataset.locationTab,id,elite));wireProposalActions();wireLocationTabs();wireEquipmentActions();wireDemoDocuments();wireConditionReportActions();wireLocationProposalActions();wirePlansActions();wireResidential()}
function activateLocationTab(tab,id,elite){document.querySelectorAll(".location-tabs button").forEach(x=>x.classList.toggle("active",x.dataset.locationTab===tab));const workspace=document.querySelector("#location-workspace"),l=LOCATIONS.find(x=>x.id===id);workspace.innerHTML=l.residential?residentialPanel():elite?(tab==="proposal"?proposalsView(id):coconutPanel(tab)):genericLocationPanel(tab,l);wirePortalLinks();wireProposalActions();wireLocationTabs();wireEquipmentActions();wireDemoDocuments();wireConditionReportActions();wireLocationProposalActions();wireResidential();workspace.scrollIntoView({behavior:"smooth",block:"start"})}
function wireLocationTabs(){document.querySelectorAll("#location-workspace [data-location-tab]").forEach(b=>b.onclick=()=>document.querySelector(`.location-tabs [data-location-tab="${b.dataset.locationTab}"]`).click())}
function wireEquipmentActions(){document.querySelectorAll("[data-report-unit]").forEach(b=>b.onclick=()=>reportUnitModal(b.dataset.reportLocation||"bmw-coconut-creek",b.dataset.reportUnit));document.querySelectorAll("[data-asset-unit]").forEach(b=>b.onclick=()=>assetDetailModal(b.dataset.assetLocation||"bmw-coconut-creek",b.dataset.assetUnit));const [,route,locationId]=location.hash.split("/"),units=locationId==="bmw-coconut-creek"?COCONUT_EQUIPMENT:ARRIGO_EQUIPMENT[locationId]?.units;if(route==="location"&&units)document.querySelectorAll(".equipment-card").forEach((card,index)=>{if(card.querySelector(".asset-detail-button"))return;const unit=units[index],button=document.createElement("button");button.type="button";button.className="button asset-detail-button";button.textContent="View asset details";button.onclick=()=>assetDetailModal(locationId,unit.id);card.append(button)})}
function wireDemoDocuments(){document.querySelectorAll("[data-demo-doc]").forEach(b=>b.onclick=()=>previewDemoDocument(b.dataset.demoDoc));document.querySelectorAll("[data-demo-open]").forEach(b=>b.onclick=()=>window.open(COCONUT_DOCS[b.dataset.demoOpen].url,"_blank","noopener"));document.querySelectorAll("[data-demo-download]").forEach(b=>b.onclick=()=>{const d=COCONUT_DOCS[b.dataset.demoDownload],a=document.createElement("a");a.href=d.url;a.download=d.url.split("/").pop();a.click()})}
